css:
:root {
  --paper: #F2EFE6;
  --paper-deep: #E7E3D5;
  --paper-light: #F8F5ED;
  --ink: #151710;
  --ink-soft: #3E4137;
  --muted: #5D6056;
  --line: rgba(21, 23, 16, 0.16);
  --line-strong: rgba(21, 23, 16, 0.42);
  --forest: #121A14;
  --cream: #F7F4EC;
  --cream-muted: rgba(247, 244, 236, 0.64);
  --accent: #C9F26C;
  --accent-deep: #9CCF3A;
  --rust: #B64428;
  --sans: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", Georgia, serif;
  --mono: ui-monospace, "SFMono-Regular", Menlo, Consolas, "Liberation Mono", monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: hidden;
  overflow-x: clip;
}

::selection {
  background: var(--accent);
  color: var(--ink);
}

a {
  color: inherit;
  text-decoration: none;
}

svg {
  display: block;
}

h1,
h2,
h3,
p {
  margin: 0;
}

ol,
ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.shell {
  width: min(1240px, calc(100% - 96px));
  margin-inline: auto;
}

.skip-link {
  position: fixed;
  top: 12px;
  left: 12px;
  z-index: 100;
  padding: 10px 14px;
  background: var(--ink);
  color: var(--cream);
  font-size: 13px;
  transform: translateY(-160%);
  transition: transform 180ms ease;
}

.skip-link:focus {
  transform: translateY(0);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

:focus-visible {
  outline: 2px solid var(--rust);
  outline-offset: 4px;
}

.closing :focus-visible {
  outline-color: var(--accent);
}

.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
  width: min(1240px, calc(100% - 96px));
  margin-inline: auto;
  padding: 22px 0;
  border-bottom: 1px solid var(--line);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
  font-size: 19px;
  font-weight: 620;
  letter-spacing: -0.035em;
}

.brand-mark {
  width: 30px;
  height: 30px;
  color: var(--ink);
}

.brand-mark svg {
  width: 100%;
  height: 100%;
}

.site-nav {
  display: flex;
  gap: 36px;
  margin-left: 54px;
  margin-right: auto;
  color: var(--ink-soft);
  font-size: 13px;
  font-weight: 520;
}

.site-nav a {
  position: relative;
  padding: 5px 0;
}

.site-nav a::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 1px;
  background: var(--ink);
  transform: scaleX(0);
  transform-origin: right;
  transition: transform 220ms ease;
}

.site-nav a:hover::after {
  transform: scaleX(1);
  transform-origin: left;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 24px;
}

.sign-in {
  font-size: 13px;
  font-weight: 520;
  color: var(--ink-soft);
}

.sign-in:hover {
  color: var(--ink);
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  min-height: 52px;
  padding: 0 7px 0 21px;
  border: 1px solid var(--ink);
  border-radius: 3px;
  font-family: var(--sans);
  font-size: 13px;
  font-weight: 620;
  letter-spacing: -0.01em;
  white-space: nowrap;
  transition: background-color 220ms ease, color 220ms ease, border-color 220ms ease;
}

.button-arrow {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  border-radius: 2px;
  background: var(--accent);
  color: var(--ink);
  transition: transform 220ms ease;
}

.button-arrow svg {
  width: 16px;
  height: 16px;
}

.button:hover .button-arrow {
  transform: translateX(2px);
}

.button--primary {
  background: var(--ink);
  color: var(--cream);
  border-color: var(--ink);
}

.button--primary:hover {
  background: #000;
}

.button--compact {
  min-height: 42px;
  padding-left: 15px;
  gap: 12px;
  font-size: 12px;
  background: transparent;
}

.button--compact .button-arrow {
  width: 30px;
  height: 30px;
}

.button--compact .button-arrow svg {
  width: 14px;
  height: 14px;
}

.text-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 0 5px;
  border-bottom: 1px solid var(--line-strong);
  font-size: 13px;
  font-weight: 620;
  transition: border-color 220ms ease;
}

.text-link svg {
  width: 14px;
  height: 14px;
  transition: transform 220ms ease;
}

.text-link:hover {
  border-color: var(--ink);
}

.text-link:hover svg {
  transform: translateX(2px);
}

.hero {
  position: relative;
  padding: clamp(58px, 7vw, 96px) 0 clamp(92px, 9vw, 132px);
}

.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.18fr) minmax(390px, 0.82fr);
  gap: clamp(42px, 5.5vw, 82px);
  align-items: center;
}

.hero-copy {
  position: relative;
  z-index: 1;
  max-width: 760px;
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: clamp(24px, 3.2vw, 38px);
  font-family: var(--mono);
  font-size: 10px;
  line-height: 1.4;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.eyebrow-dot {
  width: 7px;
  height: 7px;
  flex-shrink: 0;
  background: var(--accent-deep);
  box-shadow: 0 0 0 4px rgba(156, 207, 58, 0.16);
}

h1 {
  max-width: 760px;
  margin-left: -0.045em;
  font-family: var(--serif);
  font-size: clamp(3.6rem, 9.1vw, 8.15rem);
  font-weight: 400;
  line-height: 0.85;
  letter-spacing: -0.058em;
}

.display-accent {
  position: relative;
  z-index: 0;
  display: inline-block;
  padding-right: 0.04em;
  font-style: italic;
}

.display-accent::after {
  content: "";
  position: absolute;
  z-index: -1;
  right: -0.035em;
  bottom: 0.035em;
  left: 0.015em;
  height: 0.055em;
  border-radius: 999px;
  background: var(--accent);
  transform: rotate(-1.2deg);
}

.hero-sub {
  max-width: 43ch;
  margin-top: clamp(27px, 3.4vw, 38px);
  color: var(--ink-soft);
  font-size: clamp(1.02rem, 1.4vw, 1.18rem);
  line-height: 1.58;
  letter-spacing: -0.014em;
  text-wrap: pretty;
}

.hero-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 24px;
  margin-top: 32px;
}

.hero-note {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 38px;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.055em;
  color: var(--muted);
}

.hero-note::before {
  content: "";
  width: 28px;
  height: 1px;
  background: var(--muted);
  opacity: 0.7;
}

.hero-art {
  position: relative;
  min-width: 0;
  padding: 14px 6px 20px 12px;
}

.art-plane {
  position: absolute;
  inset: 27px 0 6px 25px;
  border-radius: 4px;
  background: var(--accent);
  transform: rotate(2.25deg);
}

.ledger-window {
  position: relative;
  z-index: 1;
  overflow: hidden;
  padding: 24px 24px 18px;
  border: 1px solid rgba(18, 26, 20, 0.9);
  border-radius: 5px;
  background:
    radial-gradient(circle at 100% 0%, rgba(201, 242, 108, 0.13), transparent 40%),
    var(--forest);
  color: var(--cream);
  box-shadow: 0 30px 65px -38px rgba(21, 23, 16, 0.65);
}

.ledger-window::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0 47px,
    rgba(247, 244, 236, 0.055) 47px 48px
  );
  opacity: 0.55;
}

.ledger-window > * {
  position: relative;
  z-index: 1;
}

.ledger-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.ledger-brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--cream);
}

.ledger-brand-mark {
  position: relative;
  width: 13px;
  height: 13px;
  border: 1px solid rgba(247, 244, 236, 0.65);
  border-radius: 1px;
}

.ledger-brand-mark::after {
  content: "";
  position: absolute;
  top: 3px;
  right: 3px;
  bottom: 3px;
  left: 3px;
  background: var(--accent);
}

.live-status {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--cream-muted);
}

.live-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 3px rgba(201, 242, 108, 0.1);
}

.ledger-intro {
  margin: 31px 0 21px;
}

.micro-label {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: rgba(247, 244, 236, 0.64);
}

.ledger-title {
  margin-top: 7px;
  font-family: var(--serif);
  font-size: clamp(1.85rem, 3vw, 2.35rem);
  font-weight: 400;
  line-height: 1;
  letter-spacing: -0.04em;
}

.ledger-progress {
  margin-bottom: 6px;
}

.progress-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: rgba(247, 244, 236, 0.64);
}

.progress-track {
  height: 3px;
  margin-top: 8px;
  background: rgba(247, 244, 236, 0.12);
  overflow: hidden;
}

.progress-track span {
  display: block;
  width: 76%;
  height: 100%;
  background: var(--accent);
}

.ledger-list {
  margin-top: 4px;
}

.ledger-row {
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 58px;
  border-top: 1px solid rgba(247, 244, 236, 0.1);
}

.ledger-row--flagged {
  position: relative;
  margin: 0 -10px;
  padding: 0 10px;
  border-left: 2px solid var(--rust);
  background: rgba(214, 84, 53, 0.1);
}

.row-check {
  display: grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border: 1px solid rgba(201, 242, 108, 0.3);
  border-radius: 50%;
  color: var(--accent);
  background: rgba(201, 242, 108, 0.06);
}

.row-check svg {
  width: 12px;
  height: 12px;
}

.row-check--flag {
  border-color: rgba(214, 84, 53, 0.55);
  color: var(--rust);
  background: rgba(214, 84, 53, 0.1);
}

.row-copy {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.row-copy strong {
  overflow: hidden;
  font-size: 12px;
  font-weight: 520;
  letter-spacing: -0.012em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.row-copy small {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.04em;
  color: rgba(247, 244, 236, 0.62);
}

.ledger-row--flagged .row-copy small {
  color: #EAA38F;
}

.row-category {
  padding: 4px 6px;
  border: 1px solid rgba(247, 244, 236, 0.16);
  border-radius: 1px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: rgba(247, 244, 236, 0.6);
  white-space: nowrap;
}

.ledger-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 2px;
  padding-top: 13px;
  border-top: 1px solid rgba(247, 244, 236, 0.16);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(247, 244, 236, 0.55);
}

.foot-flagged {
  color: #EAA38F;
}

.duplicate-note {
  position: absolute;
  z-index: 3;
  bottom: -19px;
  left: -27px;
  display: flex;
  align-items: center;
  gap: 11px;
  width: 255px;
  padding: 10px 13px;
  border: 1px solid var(--ink);
  background: var(--paper-light);
  box-shadow: 4px 4px 0 var(--ink);
  transform: rotate(-1.6deg);
}

.dupe-icon {
  position: relative;
  width: 24px;
  height: 28px;
  flex-shrink: 0;
}

.dupe-icon span {
  position: absolute;
  width: 15px;
  height: 20px;
  border: 1px solid var(--ink);
  background: var(--paper-light);
}

.dupe-icon span:first-child {
  top: 0;
  left: 0;
}

.dupe-icon span:last-child {
  right: 0;
  bottom: 0;
  background: var(--accent);
}

.dupe-copy {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.dupe-copy strong {
  font-size: 11px;
  font-weight: 650;
  letter-spacing: -0.01em;
}

.dupe-copy small {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.02em;
  color: var(--muted);
}

.stamp {
  position: absolute;
  z-index: 4;
  top: 2px;
  right: -17px;
  padding: 6px 9px;
  border: 1.5px solid var(--rust);
  background: rgba(242, 239, 230, 0.94);
  color: var(--rust);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  transform: rotate(7deg);
}

.features {
  padding: clamp(74px, 9vw, 118px) 0 clamp(82px, 9vw, 118px);
  border-top: 1px solid var(--line);
}

.section-head {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(270px, 0.55fr);
  column-gap: clamp(42px, 6vw, 88px);
  row-gap: 25px;
  align-items: end;
}

.section-marker {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--mono);
  font-size: 9px;
  line-height: 1;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--muted);
}

.section-marker span {
  padding: 4px 6px;
  border: 1px solid var(--line-strong);
  color: var(--ink);
  font-size: 8px;
  line-height: 1;
  letter-spacing: 0.07em;
}

.section-head h2,
.steps-head h2 {
  font-family: var(--serif);
  font-size: clamp(2.7rem, 5.25vw, 4.8rem);
  font-weight: 400;
  line-height: 0.96;
  letter-spacing: -0.048em;
}

.section-head h2 em,
.steps-head h2 em {
  font-style: italic;
}

.section-intro {
  max-width: 38ch;
  padding-bottom: 4px;
  color: var(--muted);
  font-size: 14.5px;
  line-height: 1.62;
  letter-spacing: -0.006em;
  text-wrap: pretty;
}

.feature-list {
  margin-top: clamp(48px, 6vw, 74px);
  border-top: 1px solid var(--ink);
}

.feature {
  display: grid;
  grid-template-columns: 34px 50px minmax(0, 1.42fr) minmax(225px, 0.78fr);
  align-items: center;
  column-gap: clamp(18px, 2.6vw, 34px);
  padding: 34px 0;
  border-bottom: 1px solid var(--line-strong);
}

.feature-number {
  align-self: start;
  padding-top: 4px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.06em;
}

.feature-icon {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border: 1px solid var(--line-strong);
  border-radius: 50%;
  color: var(--ink);
}

.feature-icon svg {
  width: 25px;
  height: 25px;
}

.feature-copy h3 {
  margin-bottom: 9px;
  font-family: var(--serif);
  font-size: clamp(1.55rem, 2.15vw, 2rem);
  font-weight: 400;
  line-height: 1.1;
  letter-spacing: -0.037em;
}

.feature-copy p {
  max-width: 56ch;
  color: var(--muted);
  font-size: 14.5px;
  line-height: 1.58;
  letter-spacing: -0.004em;
  text-wrap: pretty;
}

.feature-viz {
  width: 100%;
  max-width: 260px;
  justify-self: end;
}

.category-viz {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 7px;
}

.category-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 9px;
  border: 1px solid var(--line);
  background: var(--paper-deep);
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.category-chip:nth-child(2) {
  margin-left: 18px;
}

.category-chip:nth-child(3) {
  margin-left: 36px;
}

.chip-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
}

.chip-dot--green {
  background: var(--accent-deep);
}

.chip-dot--orange {
  background: #D8883C;
}

.chip-dot--blue {
  background: #668DB0;
}

.duplicate-viz {
  position: relative;
  height: 106px;
}

.dupe-sheet {
  position: absolute;
  width: 142px;
  height: 82px;
  border: 1px solid var(--ink);
  background: var(--paper-light);
}

.dupe-sheet--back {
  top: 5px;
  left: 7px;
  transform: rotate(-4deg);
  background: var(--paper-deep);
}

.dupe-sheet--front {
  top: 22px;
  right: 3px;
  transform: rotate(2.5deg);
  box-shadow: 4px 4px 0 rgba(21, 23, 16, 0.08);
}

.dupe-sheet--front span {
  display: block;
  height: 1px;
  margin: 13px 12px 0;
  background: var(--line-strong);
}

.dupe-sheet--front span:last-child {
  width: 58%;
  margin-top: 8px;
  background: var(--accent-deep);
}

.dupe-flag {
  position: absolute;
  z-index: 2;
  top: 0;
  right: 0;
  padding: 4px 6px;
  background: var(--rust);
  color: var(--cream);
  font-family: var(--mono);
  font-size: 7px;
  line-height: 1;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  transform: rotate(3deg);
}

.close-viz {
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1.4;
  letter-spacing: 0.045em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.close-ring {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--accent);
  color: var(--ink);
  box-shadow: inset 0 0 0 1px rgba(21, 23, 16, 0.12);
}

.close-ring svg {
  width: 20px;
  height: 20px;
}

.steps {
  padding: clamp(68px, 8.5vw, 108px) 0 clamp(56px, 7vw, 88px);
  border-top: 1px solid var(--line);
  background: var(--paper-deep);
}

.steps-head {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(270px, 0.55fr);
  column-gap: clamp(42px, 6vw, 88px);
  row-gap: 25px;
  align-items: end;
}

.steps-head .section-marker {
  grid-column: 1 / -1;
}

.step-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin-top: clamp(48px, 6vw, 72px);
  border-top: 1px solid var(--ink);
}

.step {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 208px;
  padding: 26px 36px 0 0;
  border-right: 1px solid var(--line-strong);
}

.step:not(:first-child) {
  padding-left: 34px;
}

.step:last-child {
  padding-right: 0;
  border-right: 0;
}

.step-number {
  margin-bottom: 35px;
  font-family: var(--serif);
  font-size: clamp(3.5rem, 5.2vw, 5.2rem);
  font-style: italic;
  font-weight: 400;
  line-height: 0.72;
  letter-spacing: -0.07em;
  color: var(--ink);
}

.step-copy h3 {
  margin-bottom: 7px;
  font-size: 18px;
  font-weight: 640;
  line-height: 1.25;
  letter-spacing: -0.025em;
}

.step-copy p {
  max-width: 27ch;
  color: var(--ink-soft);
  font-size: 13px;
  line-height: 1.54;
  text-wrap: pretty;
}

.step-arrow {
  position: absolute;
  top: 37px;
  right: 21px;
  color: var(--muted);
  opacity: 0.7;
}

.step-arrow svg {
  width: 42px;
  height: 14px;
}

.closing {
  position: relative;
  overflow: hidden;
  padding: clamp(72px, 8.6vw, 112px) 0 0;
  background: var(--forest);
  color: var(--cream);
}

.closing-lines {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0 79px,
    rgba(247, 244, 236, 0.055) 79px 80px
  );
}

.closing::before,
.closing::after {
  content: "";
  position: absolute;
  width: 620px;
  height: 620px;
  border: 1px solid rgba(247, 244, 236, 0.08);
  border-radius: 50%;
  pointer-events: none;
}

.closing::before {
  top: -320px;
  right: -190px;
}

.closing::after {
  right: -310px;
  bottom: -340px;
}

.closing .shell {
  position: relative;
  z-index: 1;
}

.closing-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.16fr) minmax(315px, 0.54fr);
  align-items: end;
  column-gap: clamp(42px, 7vw, 98px);
  row-gap: 30px;
}

.section-marker--light {
  margin-bottom: clamp(26px, 3.4vw, 38px);
  color: var(--cream-muted);
}

.section-marker--light span {
  border-color: rgba(247, 244, 236, 0.3);
  color: var(--cream);
}

.closing h2 {
  font-family: var(--serif);
  font-size: clamp(3.4rem, 7.2vw, 6.9rem);
  font-weight: 400;
  line-height: 0.89;
  letter-spacing: -0.058em;
}

.closing h2 .line {
  display: block;
}

.closing-accent {
  color: var(--accent);
  font-style: italic;
}

.closing-action {
  padding-bottom: 6px;
}

.closing-action > p:first-child {
  max-width: 34ch;
  color: var(--cream-muted);
  font-size: 14.5px;
  line-height: 1.62;
  text-wrap: pretty;
}

.closing-buttons {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 22px;
  margin-top: 28px;
}

.button--lime {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--ink);
}

.button--lime:hover {
  border-color: var(--accent-deep);
  background: var(--accent-deep);
}

.button--lime .button-arrow {
  background: var(--ink);
  color: var(--accent);
}

.text-link--light {
  color: var(--cream);
  border-color: rgba(247, 244, 236, 0.35);
}

.text-link--light:hover {
  border-color: var(--cream);
}

.closing-note {
  margin-top: 30px;
  color: var(--cream-muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.055em;
}

.closing-footer {
  display: flex;
  align-items: center;
  gap: 28px;
  margin-top: clamp(72px, 8vw, 106px);
  padding: 22px 0 28px;
  border-top: 1px solid rgba(247, 244, 236, 0.16);
  color: var(--cream-muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.brand--light {
  color: var(--cream);
  font-family: var(--sans);
  font-size: 15px;
  letter-spacing: -0.03em;
  text-transform: none;
}

.brand--light .brand-mark {
  width: 25px;
  height: 25px;
  color: var(--cream);
}

.brand--light .brand-mark svg {
  width: 100%;
  height: 100%;
}

.closing-footer .copyright {
  margin-left: auto;
}

.line {
  display: block;
}

@media (max-width: 1080px) {
  .shell,
  .site-header {
    width: min(100% - 64px, 1240px);
  }

  .site-nav {
    margin-left: 20px;
    gap: 26px;
  }

  .hero-grid {
    grid-template-columns: minmax(0, 1.1fr) minmax(355px, 0.9fr);
    gap: 42px;
  }

  .duplicate-note {
    left: -14px;
  }

  .feature {
    grid-template-columns: 30px 46px minmax(0, 1.35fr) minmax(215px, 0.8fr);
    column-gap: 22px;
  }
}

@media (max-width: 940px) {
  .site-nav {
    display: none;
  }

  .hero-grid {
    grid-template-columns: minmax(0, 1fr);
    gap: 58px;
  }

  .hero-copy {
    max-width: 720px;
  }

  .hero-art {
    width: 100%;
    max-width: 590px;
    margin-inline: auto;
  }

  .section-head,
  .steps-head,
  .closing-grid {
    grid-template-columns: minmax(0, 1fr);
    row-gap: 24px;
  }

  .section-intro {
    max-width: 52ch;
  }

  .feature {
    grid-template-columns: 32px 48px minmax(0, 1fr);
    align-items: start;
    padding: 30px 0;
  }

  .feature-number {
    align-self: start;
  }

  .feature-viz {
    grid-column: 3;
    max-width: 300px;
    margin-top: 10px;
  }

  .step-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .step {
    display: grid;
    grid-template-columns: 74px minmax(0, 1fr);
    min-height: 0;
    padding: 25px 0;
    border-right: 0;
    border-bottom: 1px solid var(--line-strong);
  }

  .step:not(:first-child) {
    padding-left: 0;
  }

  .step:last-child {
    border-bottom: 0;
    padding-bottom: 0;
  }

  .step-number {
    margin: 0;
    font-size: 3.5rem;
    line-height: 0.9;
  }

  .step-arrow {
    display: none;
  }

  .closing {
    padding-top: 72px;
  }

  .closing-action {
    max-width: 520px;
  }

  .closing-footer {
    margin-top: 70px;
  }
}

@media (max-width: 640px) {
  .shell,
  .site-header {
    width: calc(100% - 40px);
  }

  .site-header {
    gap: 16px;
    padding: 18px 0;
  }

  .brand {
    font-size: 17px;
    gap: 8px;
  }

  .brand-mark {
    width: 27px;
    height: 27px;
  }

  .header-actions {
    gap: 14px;
  }

  .sign-in {
    display: none;
  }

  .button--compact {
    gap: 9px;
    min-height: 38px;
    padding-left: 12px;
    font-size: 11px;
  }

  .button--compact .button-arrow {
    width: 26px;
    height: 26px;
  }

  .hero {
    padding: 42px 0 82px;
  }

  .eyebrow {
    margin-bottom: 23px;
    font-size: 9px;
    letter-spacing: 0.1em;
  }

  h1 {
    font-size: clamp(3.35rem, 15.3vw, 4.25rem);
  }

  .hero-sub {
    max-width: 34ch;
    margin-top: 24px;
    font-size: 16px;
    line-height: 1.55;
  }

  .hero-actions {
    gap: 20px;
    margin-top: 27px;
  }

  .button {
    min-height: 48px;
    padding-left: 17px;
    font-size: 12px;
  }

  .button-arrow {
    width: 34px;
    height: 34px;
  }

  .hero-note {
    margin-top: 30px;
    font-size: 9px;
  }

  .hero-art {
    padding: 10px 2px 14px 8px;
  }

  .art-plane {
    inset: 22px 0 8px 16px;
  }

  .ledger-window {
    padding: 18px 16px 14px;
  }

  .ledger-intro {
    margin: 25px 0 18px;
  }

  .ledger-title {
    font-size: 1.9rem;
  }

  .ledger-row {
    grid-template-columns: 20px minmax(0, 1fr) auto;
    gap: 8px;
    min-height: 55px;
  }

  .row-copy strong {
    font-size: 11px;
  }

  .row-category {
    padding: 4px 5px;
    font-size: 7px;
  }

  .duplicate-note {
    position: relative;
    bottom: auto;
    left: auto;
    width: calc(100% - 16px);
    margin: 12px 0 0 16px;
  }

  .stamp {
    top: -7px;
    right: 5px;
  }

  .features {
    padding: 64px 0 70px;
  }

  .section-head {
    row-gap: 20px;
  }

  .section-head h2,
  .steps-head h2 {
    font-size: clamp(2.45rem, 11.2vw, 3.1rem);
  }

  .section-intro {
    font-size: 14px;
  }

  .feature-list {
    margin-top: 38px;
  }

  .feature {
    grid-template-columns: 42px minmax(0, 1fr);
    column-gap: 14px;
    padding: 26px 0;
  }

  .feature-number {
    display: none;
  }

  .feature-icon {
    width: 40px;
    height: 40px;
  }

  .feature-icon svg {
    width: 22px;
    height: 22px;
  }

  .feature-copy {
    grid-column: 2;
  }

  .feature-copy h3 {
    margin-bottom: 7px;
    font-size: 1.55rem;
  }

  .feature-copy p {
    font-size: 14px;
    line-height: 1.55;
  }

  .feature-viz {
    grid-column: 2;
    max-width: none;
    margin-top: 14px;
  }

  .category-viz {
    flex-direction: row;
    flex-wrap: wrap;
    gap: 6px;
  }

  .category-chip:nth-child(2),
  .category-chip:nth-child(3) {
    margin-left: 0;
  }

  .duplicate-viz {
    max-width: 260px;
    height: 100px;
  }

  .dupe-sheet {
    width: 130px;
    height: 74px;
  }

  .steps {
    padding: 58px 0 52px;
  }

  .step-grid {
    margin-top: 38px;
  }

  .step {
    grid-template-columns: 58px minmax(0, 1fr);
    padding: 22px 0;
  }

  .step-number {
    font-size: 2.8rem;
  }

  .step-copy h3 {
    font-size: 17px;
  }

  .step-copy p {
    font-size: 13.5px;
  }

  .closing {
    padding-top: 60px;
  }

  .section-marker--light {
    margin-bottom: 25px;
  }

  .closing h2 {
    font-size: clamp(3.15rem, 14.5vw, 4.1rem);
    line-height: 0.92;
  }

  .closing-action > p:first-child {
    font-size: 14px;
  }

  .closing-buttons {
    gap: 20px;
    margin-top: 24px;
  }

  .closing-footer {
    flex-wrap: wrap;
    gap: 13px 20px;
    margin-top: 56px;
    padding: 20px 0 24px;
    font-size: 7px;
  }

  .closing-footer > p:not(.copyright) {
    order: 3;
    width: 100%;
  }

  .closing-footer .copyright {
    margin-left: auto;
  }
}

@media (max-width: 370px) {
  .button--compact span:first-child {
    display: none;
  }

  .button--compact {
    padding-left: 8px;
    gap: 6px;
  }

  .ledger-row {
    min-height: 52px;
  }

  .row-category {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-delay: 0ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
